create table public.frs9_amort_journal_data
(
    id                 bigserial
        primary key,
    prc_date           date,
    account_id         bigint,
    facno              varchar(50),
    cifno              varchar(50),
    acctno             varchar(70),
    datasource         varchar(20),
    prdtype            varchar(20),
    prdcode            varchar(20),
    trxcode            varchar(20),
    ccy                varchar(10),
    journalcode        varchar(20),
    journalcode2       varchar(10),
    status             varchar(20),
    reverse            varchar(3),
    flag_cf            varchar(3),
    drcr               varchar(2),
    glno               varchar(20),
    n_amount           numeric(32, 6),
    n_amount_idr       numeric(32, 6),
    sourceprocess      varchar(20),
    intmid             bigint,
    branch             varchar(20),
    noref              varchar(20),
    valctr_code        varchar(50),
    journal_desc       varchar(200),
    createddate        timestamp,
    createdby          varchar(30),
    gl_internal_code   varchar(100),
    method             varchar(10),
    reserved_varchar_1 varchar(100),
    reserved_varchar_2 varchar(100),
    reserved_varchar_3 varchar(100),
    gl_costcenter      varchar(10)
);

alter table public.frs9_amort_journal_data
    owner to postgres;

