create view public.vw_frs9_first_default
            (prc_date, account_id, rule_id, os_at_default, eqv_at_default, eir_at_default) as
WITH cte_first_default AS (SELECT frs9_default.prc_date,
                                  frs9_default.account_id,
                                  frs9_default.rule_id,
                                  frs9_default.os_at_default,
                                  frs9_default.eqv_at_default,
                                  frs9_default.eir_at_default,
                                  row_number()
                                  OVER (PARTITION BY frs9_default.account_id, frs9_default.rule_id ORDER BY frs9_default.prc_date) AS rn
                           FROM frs9_default)
SELECT prc_date,
       account_id,
       rule_id,
       os_at_default,
       eqv_at_default,
       eir_at_default
FROM cte_first_default
WHERE rn = 1;

alter table public.vw_frs9_first_default
    owner to postgres;

create view public.view_param_segment_rules
            (segment_id, group_segment, segment, sub_segment, segment_type, h_seq, active_flag, query_group, d_seq,
             table_name, column_name, data_type, operator, value1, value2, condition)
as
SELECT d.segment_id,
       h.group_segment,
       h.segment,
       h.sub_segment,
       h.segment_type,
       h.seq AS h_seq,
       h.active_flag,
       d.query_group,
       d.seq AS d_seq,
       d.table_name,
       d.column_name,
       d.data_type,
       d.operator,
       d.value1,
       d.value2,
       d.condition
FROM frs9_param_segmenth h
         JOIN frs9_param_segmentd d ON h.pkid = d.segment_id;

alter table public.view_param_segment_rules
    owner to postgres;

create view public.view_param_scenario_rules
            (rule_id, rule_name, rule_type, updated_table, updated_column, h_seq, value, active_flag, query_group,
             d_seq, table_name, column_name, data_type, operator, value1, value2, condition, detail_type, stage_from,
             stage_to)
as
SELECT h.pkid AS rule_id,
       h.rule_name,
       h.rule_type,
       h.updated_table,
       h.updated_column,
       h.seq  AS h_seq,
       h.value,
       h.active_flag,
       d.query_group,
       d.seq  AS d_seq,
       d.table_name,
       d.column_name,
       d.data_type,
       d.operator,
       d.value1,
       d.value2,
       d.condition,
       d.detail_type,
       d.stage_from,
       d.stage_to
FROM frs9_param_scenario_rulesh h
         JOIN frs9_param_scenario_rulesd d ON h.pkid = d.rule_id;

alter table public.view_param_scenario_rules
    owner to postgres;

create view public.vw_frs9_max_bucket(bucket_group, bucket_id) as
SELECT a.bucket_group,
       max(b.bucket_id) AS bucket_id
FROM frs9_param_bucketh a
         JOIN frs9_param_bucketd b ON a.pkid = b.pkid_header
GROUP BY a.bucket_group, a.bucket_default;

alter table public.vw_frs9_max_bucket
    owner to postgres;

create view public.view_imp_ca_ecl_config
            (ecl_model_id, effective_date, module, active_flag, stage_rule_id, pf_segment_id, pd_model_id, lgd_model_id,
             ead_model_id, overlay_rate, period_type, period_date, createdby)
as
SELECT h.pkid AS ecl_model_id,
       h.effective_date,
       h.module,
       h.active_flag,
       d.stage_rule_id,
       d.pf_segment_id,
       d.pd_model_id,
       d.lgd_model_id,
       d.ead_model_id,
       d.overlay_rate,
       d.period_type,
       d.period_date,
       d.createdby
FROM frs9_imp_ca_ecl_configh h
         JOIN frs9_imp_ca_ecl_configd d ON h.pkid = d.ecl_model_id;

alter table public.view_imp_ca_ecl_config
    owner to postgres;

create view public.vw_frs9_movement_snapshot
            (download_date, ecl_model_id, account_id, group_segment, account_status, stage, impaired_flag,
             exchange_rate, ecl_amount, gross_carrying_amount, restructure_flag, poci_flag)
as
SELECT a.prc_date                                                                                               AS download_date,
       a.ecl_model_id,
       a.account_id,
       lower(a.group_segment::text)                                                                             AS group_segment,
       lower(
               CASE
                   WHEN b.account_id IS NULL THEN 'A'::text
                   ELSE 'W'::text
                   END)                                                                                         AS account_status,
       a.stage,
       lower(a.impaired_status::text)                                                                           AS impaired_flag,
       COALESCE(a.exchange_rate, 1::double precision)                                                           AS exchange_rate,
       COALESCE(a.ecl_final_amt, 0::numeric)::double precision *
       COALESCE(a.exchange_rate, 1::double precision)                                                           AS ecl_amount,
       COALESCE(a.carrying_amt, 0::numeric)::double precision *
       COALESCE(a.exchange_rate, 1::double precision)                                                           AS gross_carrying_amount,
       a.restructure_flag,
       false                                                                                                    AS poci_flag
FROM frs9_master_account a
         LEFT JOIN frs9_master_account_wo b ON b.account_id = a.account_id AND b.prc_date = a.prc_date
WHERE lower(a.account_status::text) = 'a'::text
   OR b.account_id IS NOT NULL;

alter table public.vw_frs9_movement_snapshot
    owner to postgres;

create view public.vw_frs9_imp_ca_ead_process_ead_curr
            (prc_date, account_id, account_number, start_date, maturity_date, payment_start_date, stage,
             remaining_tenor, interest_rate, payment_code, interest_base, payment_term, payment_freq,
             next_sch_prin_date, int_pmt_term, int_pmt_freq, next_sch_int_date, grace_type, grace_start_date,
             grace_end_date, fib_flag, fib_start_date, fib_tenor, fib_amt, fix_principal_amt, fix_interest_amt, idays,
             eom_payment_date, payment_date, os_balance, installment, principal, interest)
as
SELECT prc_date,
       account_id,
       account_number,
       start_date,
       maturity_date,
       payment_start_date,
       stage,
       remaining_tenor,
       interest_rate,
       payment_code,
       interest_base,
       payment_term,
       payment_freq,
       next_sch_prin_date,
       int_pmt_term,
       int_pmt_freq,
       next_sch_int_date,
       grace_type,
       grace_start_date,
       grace_end_date,
       fib_flag,
       fib_start_date,
       fib_tenor,
       fib_amt,
       fix_principal_amt,
       fix_interest_amt,
       next_payment_date - payment_date                                                                          AS idays,
       next_eom_payment_date                                                                                     AS eom_payment_date,
       next_payment_date                                                                                         AS payment_date,
       os_balance -
       fn_frs9_imp_ca_ead_process_principal_amt(next_payment_date, maturity_date, os_balance, grace_type::text,
                                                grace_end_date, payment_code::text, interest_base::text, interest_rate,
                                                installment,
                                                fix_principal_amt)                                               AS os_balance,
       installment,
       fn_frs9_imp_ca_ead_process_principal_amt(next_payment_date, maturity_date, os_balance, grace_type::text,
                                                grace_end_date, payment_code::text, interest_base::text, interest_rate,
                                                installment,
                                                fix_principal_amt)                                               AS principal,
       fn_frs9_imp_ca_ead_process_interest_amt(grace_type::text, next_payment_date, grace_end_date, payment_code::text,
                                               interest_base::text, os_balance, interest_rate,
                                               fix_interest_amt)                                                 AS interest
FROM tmp_imp_ca_ead_curr m
WHERE payment_date <= maturity_date
  AND os_balance > 0::numeric;

alter table public.vw_frs9_imp_ca_ead_process_ead_curr
    owner to postgres;

